declare(strict_types=1);require_once dirname(__DIR__).'/bootstrap.php';require_method('POST');$u=current_user();require_csrf();$d=input();$current=(string)($d['currentPassword']??'');$new=(string)($d['newPassword']??'');if(strlen($new)<12||strlen($new)>128)throw new ApiError(422,'Password must be 12 to 128 characters.');$s=db()->prepare('SELECT password_hash FROM users WHERE id=? AND tenant_id=?');$s->execute([$u['id'],$u['tenant_id']]);if(!password_verify($current,(string)$s->fetchColumn()))throw new ApiError(422,'Current password is incorrect.');db()->prepare('UPDATE users SET password_hash=? WHERE id=? AND tenant_id=?')->execute([password_hash($new,PASSWORD_DEFAULT),$u['id'],$u['tenant_id']]);if(!empty($d['logoutOtherSessions']))db()->prepare('UPDATE auth_sessions SET revoked_at=UTC_TIMESTAMP() WHERE user_id=? AND tenant_id=? AND id<>? AND revoked_at IS NULL')->execute([$u['id'],$u['tenant_id'],$u['session_id']]);audit('security.password_changed','user',$u['public_id']);respond(['message'=>'Password updated.']);
